import {normalizeMix,tracks} from './mix.js';
export function suggestedInstruments(style){const defaults={melody:false,harmony:true,bass:true,drums:false,piano:true,guitar:false,violin:false};return {...defaults,...({rnb:{piano:true,guitar:true,drums:true},folk:{piano:false,guitar:true,violin:true},ballad:{piano:true,violin:true,drums:true},rock:{piano:false,guitar:true,drums:true,harmony:false},electronic:{piano:false,melody:true,drums:true}}[style]||{})}}
export function arrangerHtml(p,score){const mix=normalizeMix(p.mix),sec=n=>(n*score.duration).toFixed(1),enabled=Object.keys(tracks).filter(k=>p.instruments[k]);return `<section class="arranger" aria-label="回忆编曲台"><div class="arranger-heading"><div><div class="eyebrow">MAKE IT YOUR OWN</div><h2>你的回忆，你来编曲。</h2></div><span class="live-label">● 实时试听</span></div><p class="arranger-intro">拖动乐器的出场与离场位置，让声音像故事一样，一层层发生。</p><div class="tempo-panel"><label for="tempo">回忆的步速 <strong id="tempo-value">${score.bpm} BPM</strong></label><input id="tempo" type="range" min="60" max="150" step="1" value="${score.bpm}" aria-label="音乐速度"><div class="tempo-labels"><span>慢慢回想</span><span>轻快向前</span></div><button class="secondary" id="apply-tempo">应用速度</button><p>调整速度会重新演奏同一条旋律，保持音高。</p></div><div class="arrange-presets"><button data-preset="build">✧ 渐进展开</button><button data-preset="dialogue">♡ 双人对话</button><button data-preset="intimate">☾ 私密独白</button></div><div class="timeline-heading"><span>声音的出场顺序</span><span>起笔 · 回响 · 展开 · 余韵</span></div><div class="arrange-lanes">${enabled.map(k=>`<div class="arrange-lane" data-lane="${k}"><div class="lane-heading"><b>${tracks[k]}</b><span data-window-label="${k}">${sec(mix[k].start)}s — ${sec(mix[k].end)}s</span><button class="spotlight" data-spotlight="${k}" title="围绕当前播放位置，让此乐器成为一段高光">此刻高光</button></div><div class="window-rail" style="--from:${mix[k].start*100}%;--to:${mix[k].end*100}%"><div class="lane-grid"></div><div class="window-region"><span>♫</span></div><input class="trim-range trim-start" type="range" min="0" max="95" step="1" value="${Math.round(mix[k].start*100)}" data-mix="start" data-track-mix="${k}" aria-label="${tracks[k]}进入时间百分比"><input class="trim-range trim-end" type="range" min="5" max="100" step="1" value="${Math.round(mix[k].end*100)}" data-mix="end" data-track-mix="${k}" aria-label="${tracks[k]}离开时间百分比"></div><div class="lane-volume"><span>音量</span><input type="range" min="0" max="150" step="1" value="${Math.round(mix[k].volume*100)}" data-mix="volume" data-track-mix="${k}" aria-label="${tracks[k]}音量"><output data-volume-label="${k}">${Math.round(mix[k].volume*100)}%</output></div></div>`).join('')||'<p class="hint">先在上方选中一种乐器，再安排它的出场。</p>'}</div><div class="arrange-actions"><button class="text-btn" id="undo-arrange">撤回一次调整</button><button class="text-btn" id="reset-arrange">恢复整段演奏</button><button class="primary" id="save-arrange">保存编曲</button></div><p class="arrange-footnote">出场、离场与音量实时生效；「此刻高光」让该乐器只在当前时刻附近出现。收藏与音频下载会保留编曲。</p></section>`}
